{
  "research": [
    {
      "id": "R1",
      "title": "Probability Calibration Under Class Distribution Shift",
      "bullets": [
        "Designed experiments with supervisor guidance to compare temperature scaling and isotonic regression under controlled changes in class prevalence.",
        "Evaluated calibration curves and probabilistic losses across held-out datasets, separating calibration sample effects from changes in the test distribution."
      ]
    },
    {
      "id": "R2",
      "title": "Regularization and Feature Correlation in Sparse Regression",
      "bullets": [
        "Planned simulation experiments with supervisor guidance to examine how feature correlation and noise affect lasso and elastic net estimation.",
        "Implemented repeated sampling and nested cross-validation, summarizing coefficient stability, variable selection consistency, and prediction error across experimental conditions."
      ]
    }
  ],
  "publications": [],
  "work": [],
  "projects": [
    {
      "id": "T1",
      "title": "Comparative Evaluation of Missing-Data Imputation Strategies",
      "bullets": [
        "Implemented mean, nearest-neighbor, and iterative imputation pipelines for tabular classification, fitting preprocessing steps exclusively within training folds.",
        "Compared downstream logistic regression performance under random and feature-dependent missingness, documenting sensitivity to missingness patterns and imputation choices."
      ]
    },
    {
      "id": "T2",
      "title": "Bootstrap and Analytical Confidence Intervals for Regression",
      "bullets": [
        "Implemented percentile bootstrap, residual bootstrap, and analytical confidence intervals for linear regression coefficients using simulated datasets with known parameters.",
        "Compared empirical coverage and interval width across sample sizes and error distributions, examining departures from constant-variance assumptions."
      ]
    }
  ]
}
